m=json.load(open('/app/runs/bin_after_drop/meta.json'));c=m['cameras']['egocentric_mirrored_camera'];E=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);d=np.load('/app/runs/bin_after_drop/last_depth_egocentric_mirrored_camera.npy');im=np.array(Image.open('/app/runs/bin_after_drop/last/egocentric_mirrored_camera.jpg'));
for box in [(60,190,110,210),(70,180,100,190),(30,200,80,230)]:
 U,V=np.meshgrid(np.arange(box[0],box[1]),np.arange(box[2],box[3]));u=U.ravel();v=V.ravel();z=d[v,u];rgb=im[v,u];mask=(rgb.max(1)-rgb.min(1)<20)&(rgb[:,0]>55)&(rgb[:,0]<170)&(z>0);u=u[mask];v=v[mask];z=z[mask];p=np.stack([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z],1);w=(p-E[:,3])@E[:,:3];w=w[(w[:,2]>0)&(w[:,2]<.2)];rng=np.random.default_rng(42);best=None
